const crypto = require('crypto');
const body = $json.body || $json;
const now = new Date().toISOString();
const requestId = body.request_id || `REQ-${crypto.randomUUID().slice(0, 8).toUpperCase()}`;
const rawMessage = typeof body.raw_message === 'string' ? body.raw_message.trim() : '';
return [{
  json: {
    request_id: requestId,
    source: body.source || 'Unknown',
    received_at: body.received_at || now,
    raw_message: rawMessage,
    input_valid: rawMessage.length > 0,
    input_errors: rawMessage.length > 0 ? [] : ['raw_message is required'],
    workflow_version: $env.WORKFLOW_VERSION || '1.0.0',
    model_name: $env.GROQ_MODEL || 'llama-3.3-70b-versatile'
  }
}];

const item = $input.first().json;
const normalized = $('Normalize Input').first().json;
const allowedCategories = ['Bug Report','Feature Request','Billing Issue','Technical Question','Incident/Outage'];
const allowedPriorities = ['Low','Medium','High'];
const allowedUrgency = ['None','Low','Medium','High'];
function fallback(reason) {
  return [{ json: { ...normalized, llm_valid: false, validation_errors: [reason], category: 'Technical Question', priority: 'Low', confidence_score: 0, core_issue: 'The request could not be classified automatically.', identifiers: { account_reference: null, invoice_number: null, error_code: null, amounts: [], time_references: [], authentication_provider: null, affected_users: null }, urgency_signal: 'None', urgency_reason: 'LLM output was unavailable or invalid.', customer_impact: 'Unknown impact.', requires_follow_up_information: true, missing_information: ['Manual review required'], human_readable_summary: 'The request could not be classified automatically. Human Review should inspect the original customer message.' } }];
}
try {
  const content = item.choices?.[0]?.message?.content;
  if (!content) return fallback('LLM response content missing');
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  const errors = [];
  if (!allowedCategories.includes(parsed.category)) errors.push('Invalid category');
  if (!allowedPriorities.includes(parsed.priority)) errors.push('Invalid priority');
  if (!Number.isInteger(parsed.confidence_score) || parsed.confidence_score < 0 || parsed.confidence_score > 100) errors.push('Invalid confidence_score');
  if (!parsed.core_issue) errors.push('Missing core_issue');
  if (!parsed.identifiers || typeof parsed.identifiers !== 'object') errors.push('Missing identifiers');
  if (!allowedUrgency.includes(parsed.urgency_signal)) errors.push('Invalid urgency_signal');
  if (typeof parsed.requires_follow_up_information !== 'boolean') errors.push('Invalid requires_follow_up_information');
  if (!Array.isArray(parsed.missing_information)) errors.push('Invalid missing_information');
  if (!parsed.human_readable_summary) errors.push('Missing human_readable_summary');
  return [{ json: { ...normalized, ...parsed, llm_valid: errors.length === 0, validation_errors: errors } }];
} catch (error) {
  return fallback(`Malformed JSON: ${error.message}`);
}

const item = $input.first().json;
const normalized = $('Normalize Input').first().json;
const allowedCategories = ['Bug Report','Feature Request','Billing Issue','Technical Question','Incident/Outage'];
const allowedPriorities = ['Low','Medium','High'];
const allowedUrgency = ['None','Low','Medium','High'];
function fallback(reason) {
  return [{ json: { ...normalized, llm_valid: false, validation_errors: [reason], category: 'Technical Question', priority: 'Low', confidence_score: 0, core_issue: 'The request could not be classified automatically.', identifiers: { account_reference: null, invoice_number: null, error_code: null, amounts: [], time_references: [], authentication_provider: null, affected_users: null }, urgency_signal: 'None', urgency_reason: 'LLM output was unavailable or invalid after retry.', customer_impact: 'Unknown impact.', requires_follow_up_information: true, missing_information: ['Manual review required'], human_readable_summary: 'The request could not be classified automatically after retry. Human Review should inspect the original customer message.' } }];
}
try {
  const content = item.choices?.[0]?.message?.content;
  if (!content) return fallback('Retry response content missing');
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  const errors = [];
  if (!allowedCategories.includes(parsed.category)) errors.push('Invalid category');
  if (!allowedPriorities.includes(parsed.priority)) errors.push('Invalid priority');
  if (!Number.isInteger(parsed.confidence_score) || parsed.confidence_score < 0 || parsed.confidence_score > 100) errors.push('Invalid confidence_score');
  if (!parsed.core_issue) errors.push('Missing core_issue');
  if (!parsed.identifiers || typeof parsed.identifiers !== 'object') errors.push('Missing identifiers');
  if (!allowedUrgency.includes(parsed.urgency_signal)) errors.push('Invalid urgency_signal');
  if (typeof parsed.requires_follow_up_information !== 'boolean') errors.push('Invalid requires_follow_up_information');
  if (!Array.isArray(parsed.missing_information)) errors.push('Invalid missing_information');
  if (!parsed.human_readable_summary) errors.push('Missing human_readable_summary');
  if (errors.length) return fallback(`Retry validation failed: ${errors.join('; ')}`);
  return [{ json: { ...normalized, ...parsed, llm_valid: true, validation_errors: [] } }];
} catch (error) {
  return fallback(`Retry malformed JSON: ${error.message}`);
}

const record = { ...$json };
const amounts = Array.isArray(record.identifiers?.amounts) ? record.identifiers.amounts : [];
function numeric(v) { return typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.-]/g, '')); }
const billed = amounts.find(a => /billed|charge|invoice/i.test(a.label || ''));
const expected = amounts.find(a => /expected|contract|rate/i.test(a.label || ''));
let a = billed ? numeric(billed.value) : null;
let b = expected ? numeric(expected.value) : null;
if ((a === null || Number.isNaN(a) || b === null || Number.isNaN(b)) && amounts.length >= 2) {
  a = numeric(amounts[0].value);
  b = numeric(amounts[1].value);
}
record.billing_difference = Number.isFinite(a) && Number.isFinite(b) ? Math.abs(a - b) : null;
return [{ json: record }];

const record = { ...$json };
const text = `${record.raw_message || ''} ${record.identifiers?.authentication_provider || ''}`.toLowerCase();
let queue = 'Engineering Support';
if (record.category === 'Feature Request') queue = 'Product Management';
if (record.category === 'Billing Issue') queue = 'Billing Operations';
if (record.category === 'Incident/Outage') queue = 'Incident Response';
if (record.category === 'Technical Question') {
  queue = /(sso|authentication|auth provider|okta|identity|permission|security)/i.test(text) ? 'Identity & Security' : 'Engineering Support';
}
record.recommended_queue = queue;
return [{ json: record }];

const record = { ...$json };
const reasons = [];
const message = String(record.raw_message || '').toLowerCase();
const affected = String(record.identifiers?.affected_users || '').toLowerCase();
const phrases = ['outage','down for all users','dashboard stopped loading','multiple users affected','service unavailable'];
if (!record.llm_valid) reasons.push(`LLM output invalid or incomplete: ${(record.validation_errors || []).join('; ')}`);
if ((record.confidence_score ?? 0) < 70) reasons.push('Confidence score below 70');
if (record.category === 'Incident/Outage' || /(outage|unavailable|stopped loading|down)/i.test(message)) reasons.push('Message indicates service outage or unavailability');
if (/(multiple users|all users|everyone|company-wide)/i.test(`${message} ${affected}`)) reasons.push('Multiple users or all users are affected');
for (const phrase of phrases) if (message.includes(phrase)) reasons.push(`Message contains escalation phrase: ${phrase}`);
if (record.category === 'Billing Issue' && typeof record.billing_difference === 'number' && record.billing_difference > 500) reasons.push('Billing discrepancy greater than $500');
record.escalation_reasons = [...new Set(reasons)];
record.escalation_flag = record.escalation_reasons.length > 0;
return [{ json: record }];

const record = { ...$json };
record.final_queue = record.escalation_flag ? 'Human Review' : record.recommended_queue;
return [{ json: record }];
